import json
d=json.load(open('research/modalities/hla-coverage.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            walk(v,p+'.'+k)
    elif isinstance(o,list):
        print(p,'= LIST len',len(o), repr(o)[:200])
    else:
        print(p,'=',repr(o)[:200])
walk(d)
EOF

