for k,v in d.items():
    if isinstance(v,(str,int,float,bool)) or v is None:
        print(k,'=',json.dumps(v,ensure_ascii=False)[:1200])
    elif isinstance(v,list):
        print(k,'= LIST len',len(v)); print('  sample:',json.dumps(v[:2],ensure_ascii=False)[:800])
    else:
        print(k,'= DICT keys',list(v.keys())[:30])
EOF

